BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('ap-server-q41', 'キャパシティプランニングと性能評価',
   'あるサーバーが1分間に300件のリクエストを処理できる。このサーバーの「スループット」を1秒あたりの件数で表すといくつか。',
   NULL::text,
   '["5件/秒", "300件/秒", "60件/秒", "0.2件/秒"]',
   0, '[0]', 'single',
   '{"asked":"1分あたりの処理件数から、1秒あたりのスループットを計算する問題。","why_asked":"スループットは「単位時間あたりにどれだけ処理できるか」という能力の指標で、応用情報の性能評価分野の基礎。単位の換算を正しくできるかが問われる。","kid":"スループットは「1秒間に何件さばけるか」という処理能力のこと。1分間に300件処理できるなら、1分=60秒で割れば1秒あたりの件数が出る。","eg":"たとえるなら、レジが1分間に300人をさばけるお店で、1秒あたり何人さばいているかを知りたいときの計算と同じ。","terms":[["スループット","単位時間あたりにシステムが処理できる件数。処理能力の指標"]],"calc":{"steps":["問題: 1分間に300件処理できるサーバーの、1秒あたりの処理件数を求める","ステップ1: 1分は60秒なので、300件を60秒で割ればよい","ステップ2: 300 ÷ 60 = 5","答え: 1秒あたり5件（5件/秒）"],"formula":"スループット(件/秒) = 1分間の処理件数 ÷ 60"},"think":"「1分あたり」から「1秒あたり」に変換するには、分を秒に直す換算（×60 or ÷60）をどちらの向きに使うかがポイント。1分より1秒の方が短い時間なので、1秒あたりの件数は1分あたりより少なくなる、つまり割り算になる。","vs":"レスポンスタイム（1件の処理にかかる時間）と混同しやすいが、スループットは「単位時間あたりの件数」で、レスポンスタイムは「1件あたりの時間」という逆向きの指標。","opt":["正解。300件÷60秒=5件/秒。","300をそのまま使っており、単位（分→秒）の換算をしていない値。","300÷5のような無関係な計算をした値。","300÷60の逆数（60÷300）を計算してしまった値。"]}'),

  ('ap-server-q42', 'キャパシティプランニングと性能評価',
   'システムに処理を依頼してから、最初の反応（応答）が返ってくるまでの時間を指す用語として最も適切なものはどれか。',
   NULL::text,
   '["レスポンスタイム", "スループット", "ターンアラウンドタイム", "MTBF"]',
   0, '[0]', 'single',
   '{"asked":"「依頼してから最初の反応が返るまでの時間」を表す性能指標を選ぶ問題。","why_asked":"レスポンスタイムとターンアラウンドタイムは「時間」を表す指標として名前が似ており、応用情報でも取り違えやすい定番の論点。","kid":"レスポンスタイムは「話しかけてから、最初に返事が返ってくるまでの時間」。全部の処理が終わるまでではなく、あくまで「最初の反応」までの時間を指す。","eg":"たとえるなら、お店で店員さんに声をかけてから「はい、少々お待ちください」と返事をもらうまでの時間。注文の品が実際に運ばれてくるまでの時間とは別。","terms":[["レスポンスタイム","処理を依頼してから、最初の応答が返るまでの時間"],["ターンアラウンドタイム","処理を依頼してから、すべての結果が返るまでの時間"]],"think":"「最初の反応」か「全部の完了」かで見分ける。レスポンスタイムは前者、ターンアラウンドタイムは後者を指す。両方とも「時間」を表す指標なので、どの区間を測っているかで区別する。","vs":"ターンアラウンドタイムと混同しやすいが、ターンアラウンドタイムは処理が完全に終わるまでの時間で、レスポンスタイムより長くなるのが普通。","opt":["正解。依頼してから最初の応答が返るまでの時間。","スループットは単位時間あたりの処理件数で、1回の依頼にかかる時間ではない。","ターンアラウンドタイムは依頼してから全部の結果が返るまでの時間で、最初の反応だけを指すものではない。","MTBFは故障してから次の故障までの平均時間で、性能評価ではなく信頼性の指標。"]}'),

  ('ap-server-q43', 'キャパシティプランニングと性能評価',
   'あるサーバーが1時間のうち45分間、実際に処理でふさがっていた。このサーバーの「利用率」はいくつか。',
   NULL::text,
   '["75%", "45%", "60%", "15%"]',
   0, '[0]', 'single',
   '{"asked":"稼働時間のうち実際に処理していた時間の割合から利用率を計算する問題。","why_asked":"利用率は待ち行列理論の入り口で、待ち時間の長さと直結する重要な指標。まず単純な割合計算として押さえる。","kid":"利用率は「決められた時間のうち、実際にどれだけ働いていたか」の割合。1時間(60分)のうち45分ふさがっていたなら、45を60で割れば割合が出る。","eg":"たとえるなら、1時間のうち45分お客さんの対応をしていたレジ係の「稼働率」を求めるのと同じ計算。","terms":[["利用率","ある時間のうち、システムが実際に処理でふさがっていた時間の割合"]],"calc":{"steps":["問題: 60分のうち45分ふさがっていたときの利用率を求める","ステップ1: 割合は「ふさがっていた時間 ÷ 全体の時間」で求める","ステップ2: 45 ÷ 60 = 0.75","ステップ3: 0.75を百分率に直す。0.75 × 100 = 75","答え: 利用率は75%"],"formula":"利用率 = ふさがっていた時間 ÷ 全体の時間 × 100"},"think":"割合の基本計算（部分÷全体）がそのまま使える。分子に「ふさがっていた時間」、分母に「全体の時間」を置くことさえ間違えなければ、あとは小学校レベルの割り算。","vs":"稼働率（あとで学ぶ稼働率とシステムの信頼性の分野の用語）と字面が似ているが、こちらは「1台の処理能力のうちどれだけ使われているか」という負荷の指標で、システムが正常に動いている確率を表す稼働率とは別の概念。","opt":["正解。45÷60=0.75、つまり75%。","45と60の差(15)を60で割った値(25%)に近いが、この問題の答えではない。","45÷75のような無関係な計算をした値に近い。","45÷60の計算を間違えて15%と出してしまった値。"]}'),

  ('ap-server-q44', 'キャパシティプランニングと性能評価',
   'サーバーの利用率が上がっていくとき、平均の待ち時間はどのように変化する傾向があるか。',
   NULL::text,
   '["利用率が100%に近づくほど、待ち時間は急激に長くなっていく", "利用率が上がっても、待ち時間は常に一定のまま変わらない", "利用率が上がるほど、待ち時間はゆるやかに短くなっていく", "利用率と待ち時間には規則性がなく、無関係である"]',
   0, '[0]', 'single',
   '{"asked":"利用率と待ち時間の関係の傾向を問う問題（待ち行列理論の直感的な理解）。","why_asked":"待ち行列理論の一番大事な直感は「利用率100%に近づけすぎると待ち時間が爆発的に伸びる」という点。数式を覚えるより先に、この傾向を理解しているかを問う。","kid":"サーバーの利用率が低いうちは、待ち時間はあまり増えない。でも利用率が100%に近づいていくと、ちょっとした混雑でもすぐに列が長くなり、待ち時間が急に伸びていく。","eg":"たとえるなら、レジがガラガラなお店では並んでもすぐ会計できるけど、レジがほぼフル稼働のお店ではちょっとお客さんが増えただけで長い行列ができてしまう、というイメージ。","terms":[["待ち行列理論","処理をする窓口(サーバー)と、そこに並ぶ列(キュー)の関係を数学的に扱う理論"],["利用率","窓口がどれだけの割合でふさがっているかを表す値。0〜100%（0〜1）で表す"]],"think":"利用率が低い間は余裕があるので待ち時間の伸びもゆるやか。しかし利用率が100%に近づくと「次の客が来る前に処理が終わる余裕」がほとんど無くなり、少しの変動でも行列がどんどん積み上がっていく。この「余裕が減るほど変動に弱くなる」という関係が、待ち時間の急激な増加として現れる。","vs":"「利用率が高い＝効率が良い」と直感的に思いがちだが、待ち時間の観点では利用率を100%に近づけすぎるとサービスの質(待ち時間)が急激に悪化するというトレードオフがある。","opt":["正解。利用率が100%に近づくほど、待ち時間は急激に長くなる傾向がある。","利用率が上がると待ち時間も増える傾向があり、一定のままではない。","利用率が上がると待ち時間は伸びる傾向があり、短くなるわけではない。","利用率と待ち時間には「利用率が高いほど待ち時間が伸びやすい」という明確な傾向がある。"]}'),

  ('ap-server-q45', 'キャパシティプランニングと性能評価',
   '3つの工程A(1時間に100件処理可能)、B(1時間に60件処理可能)、C(1時間に90件処理可能)を順番に通して処理するシステム全体の、1時間あたりの処理能力(スループット)はいくつか。',
   NULL::text,
   '["60件", "100件", "90件", "250件"]',
   0, '[0]', 'single',
   '{"asked":"直列につながった複数工程のうち、システム全体のスループットがどう決まるかを問う問題。","why_asked":"「システム全体の性能は一番遅い工程で決まる」というボトルネックの考え方は、応用情報の性能評価分野の頻出論点。","kid":"複数の工程を順番に通す流れ作業では、どんなに速い工程があっても、一番遅い工程のペースにシステム全体が合わせるしかない。だからシステム全体の処理能力は、一番遅い工程の処理能力と同じになる。","eg":"たとえるなら、100人さばける受付、60人さばける会計、90人さばける発送、と3つの窓口を順番に通る行列があったら、一番遅い会計(60人)のペースに全体が引きずられて、1時間で60人しか最後まで進めない、というイメージ。","terms":[["ボトルネック","複数の工程の中で、全体の速さを決めてしまう一番遅い工程"],["直列","前の工程が終わってから次の工程に進む、一列につながった処理の流れ"]],"calc":{"steps":["問題: A=100件/時、B=60件/時、C=90件/時が直列につながったときの全体のスループットを求める","ステップ1: 直列の流れ作業では、全体の速さは一番遅い工程に引きずられる","ステップ2: A・B・Cの中で一番小さい値を探す。100、60、90のうち一番小さいのは60","答え: システム全体のスループットは60件/時"],"formula":"直列システムのスループット = min(各工程のスループット)"},"think":"直列(順番に通す)システムでは、各工程の処理能力の中の最小値がシステム全体の処理能力になる。3つを単純に足したり平均したりするのではなく、「一番遅い工程がボトルネックになる」という考え方がポイント。","vs":"3つの処理能力を単純に合計してしまう(250件)のはよくある誤り。並列に3つの窓口が独立に処理する場合と、順番に1本の流れで通す場合とでは、計算の考え方がまったく違う。","opt":["正解。3つの中で一番小さいB(60件/時)が全体のスループットを決める。","一番速い工程Aの値であり、直列システムでは実現できない値。","真ん中の値であり、ボトルネックの考え方に基づいた値ではない。","3つの処理能力を単純に足し算した値で、直列システムのスループットの求め方ではない。"]}'),

  ('ap-server-q46', 'キャパシティプランニングと性能評価',
   '将来のアクセス増加やデータ量の増加をあらかじめ見積もり、必要なサーバーやストレージの容量に余裕を持たせて計画することを何と呼ぶか。',
   NULL::text,
   '["キャパシティプランニング", "ロードバランシング", "フェイルオーバー", "サービスレベルアグリーメント"]',
   0, '[0]', 'single',
   '{"asked":"将来の負荷増加を見越して容量に余裕を持たせる計画を指す用語を選ぶ問題。","why_asked":"性能評価の知識は「今の性能を測ること」だけでなく「将来どれだけ必要になるかを見積もること」にもつながる、という接続を問う。","kid":"キャパシティプランニングは「これからどれくらいお客さんが増えそうか」をあらかじめ考えて、サーバーやストレージの容量を余裕を持って用意しておく計画のこと。","eg":"たとえるなら、お店を出すときに「将来お客さんが増えても大丈夫なように、席数や在庫を多めに見積もっておく」ような計画のイメージ。","terms":[["キャパシティプランニング","将来の負荷増加を見積もり、必要な処理能力・容量をあらかじめ計画すること"]],"think":"「将来を見積もって」「余裕を持たせる」という2つのキーワードがキャパシティプランニングを見分ける決め手。今の性能を測るだけでなく、未来の需要予測が入っている点が特徴。","vs":"ロードバランシング（今ある負荷を複数のサーバーに分散させる仕組み）と混同しやすいが、キャパシティプランニングは「そもそもどれだけの容量を用意しておくか」という事前の計画であり、負荷分散という実行時の仕組みとは段階が異なる。","opt":["正解。将来の負荷増加を見積もり、容量に余裕を持たせて計画すること。","ロードバランシングは既にある負荷を複数のサーバーに分散させる仕組みで、将来の見積もり計画とは異なる。","フェイルオーバーは障害発生時に自動的に別の系に切り替える仕組みで、容量計画とは異なる。","サービスレベルアグリーメントはサービス提供者と利用者の間で交わす品質の合意で、容量計画そのものではない。"]}'),

  ('ap-server-q47', 'キャパシティプランニングと性能評価',
   '利用者から見た「レスポンスタイム」は、内部的にはどのような時間の合計として説明できるか。',
   NULL::text,
   '["行列で待たされている待ち時間と、実際に処理されている処理時間の合計", "処理時間だけであり、待ち時間は関係しない", "待ち時間だけであり、処理時間は関係しない", "スループットをレスポンスタイムで割った値"]',
   0, '[0]', 'single',
   '{"asked":"レスポンスタイムの内訳（待ち時間＋処理時間）を問う問題。","why_asked":"「利用率が上がると待ち時間が伸びる」という前問の理解を、実際に利用者が体感するレスポンスタイムにつなげる問題。","kid":"利用者が「遅いな」と感じるレスポンスタイムは、実は「順番待ちしている時間」と「実際に処理してもらっている時間」の2つを足したもの。混雑しているときは、処理そのものは速くても、待ち時間のせいで全体が遅く感じられる。","eg":"たとえるなら、レジでの待ち時間は「行列に並んでいる時間」＋「実際に会計してもらっている時間」の合計。行列が長ければ、会計自体は一瞬でも全体としては遅く感じる。","terms":[["待ち時間","行列に並んでいて、まだ処理が始まっていない時間"],["処理時間","実際に処理が行われている時間"]],"think":"利用率が上がると待ち時間が急激に伸びる（前問）が、レスポンスタイムはその待ち時間に処理時間を足したもの。だから利用率が高い状況では、処理自体は変わらなくてもレスポンスタイムが大きく悪化する、という因果関係でつながっている。","vs":"処理時間だけがレスポンスタイムだと誤解しやすいが、混雑時は待ち時間の方が支配的になることが多く、待ち時間を無視した性能評価は実態とずれる。","opt":["正解。行列での待ち時間と、実際の処理時間の合計がレスポンスタイム。","処理時間だけでは、行列が混雑しているときの体感の遅さを説明できない。","待ち時間だけでは、実際に処理そのものにかかる時間が無視されてしまう。","スループットとレスポンスタイムは別々の指標で、割り算で片方から片方が出るものではない。"]}'),

  ('ap-server-q48', 'バックアップとディザスタリカバリ',
   'その時点で存在するすべてのデータを、丸ごとコピーして保存するバックアップ方式を何と呼ぶか。',
   NULL::text,
   '["フルバックアップ", "差分バックアップ", "増分バックアップ", "スナップショット"]',
   0, '[0]', 'single',
   '{"asked":"すべてのデータを丸ごとコピーするバックアップ方式の名前を選ぶ問題。","why_asked":"差分・増分バックアップとの比較の土台になる、一番基本のバックアップ方式。","kid":"フルバックアップは「今あるデータを全部まるごとコピーしておく」という一番シンプルな方式。データ量が多いとバックアップに時間がかかるけど、復元するときはそのコピーを戻すだけで済む。","eg":"たとえるなら、部屋の中身を全部まるごと写真に撮っておくようなもの。撮影(バックアップ)には時間がかかるけど、後で見返す(復元する)ときは1枚の写真を見ればすべてわかる。","terms":[["フルバックアップ","ある時点のデータをすべて丸ごとコピーして保存するバックアップ方式"]],"think":"「すべて」「丸ごと」というキーワードがフルバックアップを見分ける決め手。差分・増分バックアップはこのフルバックアップを起点にして、その後の変更分だけを保存する方式として位置づけられる。","vs":"差分・増分バックアップと混同しやすいが、それらは「前回からの変更分だけ」を保存するのに対し、フルバックアップは毎回すべてを保存する点が違う。","opt":["正解。ある時点のデータをすべて丸ごとコピーして保存する方式。","差分バックアップは前回のフルバックアップからの変更分だけを保存する方式で、丸ごとではない。","増分バックアップは直前のバックアップからの変更分だけを保存する方式で、丸ごとではない。","スナップショットはある瞬間の状態を記録する仕組みで、バックアップの分類（フル/差分/増分）とは別の切り口の用語。"]}'),

  ('ap-server-q49', 'バックアップとディザスタリカバリ',
   '毎回、前回の「フルバックアップ」からの変更分だけをコピーして保存していくバックアップ方式を何と呼ぶか。',
   NULL::text,
   '["差分バックアップ", "フルバックアップ", "増分バックアップ", "ミラーリング"]',
   0, '[0]', 'single',
   '{"asked":"直近のフルバックアップからの変更分だけを毎回保存する方式を選ぶ問題。","why_asked":"差分バックアップと増分バックアップは「起点をどこに取るか」という一点の違いで取り違えやすい、定番の引っかけ論点。","kid":"差分バックアップは「一番最初のフルバックアップと比べて、何が変わったか」を毎回まとめて保存する方式。2日目も3日目も、比べる相手は常に同じ「最初のフルバックアップ」。","eg":"たとえるなら、月曜日に部屋全体の写真を撮った後、火曜日は「月曜と比べて何が変わったか」、水曜日も「月曜と比べて何が変わったか」を毎回まとめて記録するイメージ。比べる基準はずっと月曜日のまま。","terms":[["差分バックアップ","直近のフルバックアップと比べた変更分を、毎回まとめて保存する方式"]],"think":"「比べる相手が常に固定（最初のフルバックアップ）」という点が差分バックアップの特徴。日が経つほど「変更分」自体は積み重なって大きくなっていくが、復元するときはフルバックアップ＋最新の差分の2つだけで済む。","vs":"増分バックアップと混同しやすいが、増分バックアップは「比べる相手が毎回直前のバックアップに変わる」点が違う。差分は比べる基準が固定、増分は基準が毎回動く、と覚える。","opt":["正解。直近のフルバックアップと比べた変更分を、毎回まとめて保存する方式。","フルバックアップはすべてを丸ごと保存する方式で、変更分だけを保存する方式ではない。","増分バックアップは直前のバックアップ(フルまたは増分)からの変更分を保存する方式で、比べる基準が毎回変わる点が差分と違う。","ミラーリングは複数のディスクに同じ内容を同時に書き込む仕組みで、バックアップの取り方の分類とは別の概念(RAID1で扱う話題)。"]}'),

  ('ap-server-q50', 'バックアップとディザスタリカバリ',
   '毎回、直前の「バックアップ（フルまたは増分）」からの変更分だけをコピーして保存していくバックアップ方式を何と呼ぶか。',
   NULL::text,
   '["増分バックアップ", "フルバックアップ", "差分バックアップ", "レプリケーション"]',
   0, '[0]', 'single',
   '{"asked":"直前のバックアップからの変更分だけを毎回保存する方式を選ぶ問題。","why_asked":"差分バックアップとの違い（比べる基準が固定か、毎回動くか）を理解しているかを問う。","kid":"増分バックアップは「前回のバックアップと比べて何が変わったか」を毎回保存する方式。比べる相手は月曜のフルバックアップだけでなく、火曜のバックアップとも比べる、というふうに比べる基準が毎回1つ前にずれていく。","eg":"たとえるなら、月曜に部屋全体の写真を撮った後、火曜は「月曜と比べた変化」を記録し、水曜は「火曜と比べた変化」を記録する、というふうに、比べる相手が常に前日にずれていくイメージ。","terms":[["増分バックアップ","直前のバックアップ（フルまたは増分）と比べた変更分だけを保存する方式"]],"think":"増分バックアップは比べる基準が毎回動くので、1回あたりのバックアップ量は少なく済み、バックアップにかかる時間も短い。ただし復元するときはフルバックアップ＋それ以降のすべての増分を順番に適用する必要があるため、差分バックアップより復元の手間がかかる。","vs":"差分バックアップと混同しやすいが、差分は比べる基準が常に最初のフルバックアップで固定、増分は比べる基準が毎回直前のバックアップに変わる点が違う。","opt":["正解。直前のバックアップ（フルまたは増分）と比べた変更分だけを保存する方式。","フルバックアップはすべてを丸ごと保存する方式で、変更分だけを保存する方式ではない。","差分バックアップは比べる基準が常に最初のフルバックアップで固定される方式で、比べる基準が毎回動く増分とは違う。","レプリケーションはデータをリアルタイムで別の場所に複製し続ける仕組みで、定期的に差分を保存するバックアップの分類とは別の概念。"]}'),

  ('ap-server-q51', 'バックアップとディザスタリカバリ',
   '月曜にフルバックアップを取り、火曜・水曜と2日連続で増分バックアップを取った場合、水曜のデータを復元するために必要なバックアップの数はいくつか。',
   NULL::text,
   '["3つ（月・火・水のすべて）", "1つ（水曜の増分バックアップだけ）", "2つ（月曜と水曜のバックアップだけ）", "0（バックアップは不要）"]',
   0, '[0]', 'single',
   '{"asked":"増分バックアップで復元するときに、なぜすべてのバックアップを順番に適用する必要があるかを問う問題。","why_asked":"増分バックアップの「復元の手間がかかる」という弱点を、具体的な日数で確認させる計算寄りの問題。","kid":"増分バックアップは「前回との差分」しか保存していないので、水曜の状態を完全に復元するには、月曜のフルバックアップに火曜の差分を足し、さらに水曜の差分を足す、というふうに順番にすべて重ねていく必要がある。1つでも欠けると正しく復元できない。","eg":"たとえるなら、月曜の写真に「火曜に変わった部分」を貼り足し、さらに「水曜に変わった部分」を貼り足していく作業。途中の1枚でも無くすと、正しい水曜の姿が組み立てられない。","terms":[["増分バックアップ","直前のバックアップからの変更分だけを保存する方式。復元には途中のすべてが必要"]],"calc":{"steps":["問題: 月曜=フル、火曜=増分、水曜=増分のとき、水曜の状態を復元するのに必要なバックアップの数を数える","ステップ1: 増分バックアップは「直前との差分」しか記録していないため、途中を飛ばせない","ステップ2: 月曜のフル + 火曜の増分 + 水曜の増分、の3つをこの順番ですべて適用する必要がある","答え: 3つ（月・火・水のすべて）"],"formula":"増分バックアップの復元に必要な数 = フルバックアップ1つ + それ以降の増分バックアップすべて"},"think":"差分バックアップなら「フル＋最新の差分」の2つで済むが、増分バックアップは差分を積み重ねる方式なので、途中の1つでも欠けると鎖がつながらず正しく復元できない。この「復元に必要な個数が日数とともに増えていく」という点が増分バックアップの弱点として説明される。","vs":"差分バックアップと混同しやすいが、差分バックアップなら同じ状況で必要なのは「月曜のフル＋水曜の差分」の2つだけで済む。この復元の手間の違いが、差分と増分を使い分ける理由になっている。","opt":["正解。月・火・水のすべてのバックアップを順番に適用する必要がある。","増分バックアップは差分の積み重ねなので、水曜のバックアップだけでは月曜からの変化がすべて含まれていない。","月曜と水曜だけでは、火曜の変更分が抜け落ちてしまい、正しく復元できない。","何らかのバックアップを適用しなければ、データを元の状態に戻すことはできない。"]}'),

  ('ap-server-q52', 'バックアップとディザスタリカバリ',
   '障害が起きたときに「どれくらいの時間で復旧させたいか」という目標を表す指標を何と呼ぶか。',
   NULL::text,
   '["RTO（目標復旧時間）", "RPO（目標復旧時点）", "MTBF（平均故障間隔）", "SLA（サービスレベルアグリーメント）"]',
   0, '[0]', 'single',
   '{"asked":"障害からどれくらいの時間で復旧させたいかという目標を表す指標を選ぶ問題。","why_asked":"RTOとRPOは名前も略語も似ており、「時間」と「時点」のどちらを表すかで混同しやすい定番の論点。","kid":"RTOは「障害が起きてから、どれくらいの時間で復旧させたいか」という目標。復旧までにかかってよい時間の長さを表している。","eg":"たとえるなら、「停電から何分以内に電気を復旧させたいか」という目標のようなもの。","terms":[["RTO","Recovery Time Objectiveの略。直訳は「復旧・時間・目標」。障害からどれくらいの時間で復旧させたいかという目標"],["RPO","Recovery Point Objectiveの略。直訳は「復旧・時点・目標」。どの時点の状態まで復旧させたいかという目標（RTOとは別の指標）"]],"think":"RTOの「T」はTime（時間）、つまり「復旧にかけてよい時間の長さ」を表す。一方RPOの「P」はPoint（時点）で、「どの時点のデータまで戻せればよいか」を表す、という違いで区別する。","vs":"RPO（目標復旧時点）と混同しやすいが、RTOは「復旧までの時間の長さ」、RPOは「どの時点のデータまで許容できるか」という別の軸の指標。","opt":["正解。障害からどれくらいの時間で復旧させたいかという目標。","RPOはどの時点のデータまで復旧できればよいかという目標で、時間の長さではなく時点を表す。","MTBFは故障してから次の故障までの平均時間で、復旧目標ではなく信頼性の指標。","SLAはサービス提供者と利用者の間で交わす品質の合意全般を指し、復旧時間の目標だけを表す言葉ではない。"]}'),

  ('ap-server-q53', 'バックアップとディザスタリカバリ',
   '「障害が起きても、どの時点のデータまでなら失ってもよいか」という許容範囲を表す指標を何と呼ぶか。',
   NULL::text,
   '["RPO（目標復旧時点）", "RTO（目標復旧時間）", "MTTR（平均修復時間）", "稼働率"]',
   0, '[0]', 'single',
   '{"asked":"どの時点のデータまで失ってもよいかという許容範囲を表す指標を選ぶ問題。","why_asked":"RTOと対になる指標として、RPOの意味（時間ではなく時点）を正しく理解しているかを問う。","kid":"RPOは「最悪の場合、どの時点のデータまで失ってもよいか」という許容範囲。バックアップを1時間おきに取っていれば、最悪でも1時間分のデータしか失わない、という考え方につながる。","eg":"たとえるなら、日記を書くとき「最悪でも昨日書いた分までは残しておきたい」という許容範囲を決めるようなもの。バックアップの頻度は、このRPOをどれだけ短く設定するかで決まってくる。","terms":[["RPO","どの時点のデータまで復旧できればよいかという許容範囲。バックアップの頻度と直結する"]],"think":"RPOを短く（1時間おきなど）設定するほど、バックアップの頻度を上げる必要がある。逆にRPOを長く許容できるなら、バックアップの頻度を下げてコストを抑えられる、というトレードオフがある。","vs":"RTO（目標復旧時間）と混同しやすいが、RTOは「復旧にかけてよい時間の長さ」、RPOは「どの時点のデータまで失ってよいか」という別の軸。RTOは復旧のスピード、RPOはバックアップの頻度に関わる、という違いで覚える。","opt":["正解。障害時にどの時点のデータまで失ってもよいかという許容範囲。","RTOは復旧にかけてよい時間の長さを表す指標で、失ってよいデータの時点を表すものではない。","MTTRは故障してから修復が終わるまでの平均時間で、データの時点の許容範囲を表す指標ではない。","稼働率はシステムが正常に動いている時間の割合を表す指標で、データの時点の許容範囲とは別の概念。"]}'),

  ('ap-server-q54', 'バックアップとディザスタリカバリ',
   '大規模な災害やシステム障害が起きても、重要な業務をできるだけ止めずに継続、または短時間で再開できるようにあらかじめ立てておく計画を何と呼ぶか。',
   NULL::text,
   '["BCP（事業継続計画）", "RTO（目標復旧時間）", "SLA（サービスレベルアグリーメント）", "キャパシティプランニング"]',
   0, '[0]', 'single',
   '{"asked":"災害・障害時にも業務を継続・再開できるようにする計画全体を指す用語を選ぶ問題。","why_asked":"RTO/RPOという個別の目標値と、それらを含む全体計画であるBCPとの関係（部分と全体）を理解しているかを問う。","kid":"BCPは「大きな災害やトラブルが起きても、大事な仕事をできるだけ止めない、または早く再開できるようにする」という、会社全体の計画。RTOやRPOは、このBCPの中で使われる具体的な数値目標の一部。","eg":"たとえるなら、地震が来たときに「どの業務を優先して守るか」「どれくらいの時間で再開させるか」をあらかじめ決めておく、防災計画のようなもの。","terms":[["BCP","Business Continuity Planの略。直訳は「事業・継続・計画」。災害や障害時にも業務を継続・再開できるようにする計画"]],"think":"BCPは会社全体の「災害・障害への備え」という大きな枠組みで、その中の具体的な数値目標としてRTO（復旧までの時間）やRPO（失ってよいデータの範囲）が使われる、という部分と全体の関係で理解する。","vs":"RTO・RPOと混同しやすいが、RTO・RPOはBCPの中で使われる個別の数値目標であり、BCPはそれらを含めた業務全体の継続計画という、より広い概念。","opt":["正解。災害・障害時にも業務を継続・再開できるようにする、会社全体の計画。","RTOは復旧にかけてよい時間という個別の数値目標で、業務全体の継続計画そのものではない。","SLAはサービス提供者と利用者の間で交わす品質の合意で、災害時の業務継続計画とは別の枠組み。","キャパシティプランニングは将来の負荷増加を見積もる容量計画で、災害・障害への備えとは目的が異なる。"]}'),

  ('ap-server-q55', 'ストレージ技術の基礎',
   'サーバーの筐体に直接接続され、そのサーバーからしか使えないストレージの接続形態を何と呼ぶか。',
   NULL::text,
   '["DAS（直接接続ストレージ）", "NAS（ネットワーク接続ストレージ）", "SAN（ストレージエリアネットワーク）", "CDN（コンテンツ配信ネットワーク）"]',
   0, '[0]', 'single',
   '{"asked":"サーバーに直接接続されたストレージの接続形態を選ぶ問題。","why_asked":"NAS・SANとの比較の出発点になる、一番シンプルなストレージの形態。","kid":"DASは、サーバーのパソコンにディスクを直接つなぐだけの、一番シンプルなストレージの形。パソコンに外付けハードディスクを直接つなぐのと同じイメージで、そのサーバーからしか使えない。","eg":"たとえるなら、自分の机の引き出しに入っている書類のようなもの。自分（そのサーバー）はすぐ使えるけど、他の人（他のサーバー）が勝手に取り出すことはできない。","terms":[["DAS","Direct Attached Storageの略。直訳は「直接・接続された・ストレージ」。サーバーに直接接続され、そのサーバー専用のストレージ"]],"think":"「直接つながっている」「そのサーバー専用」という2点がDASの特徴。ネットワーク越しに複数のサーバーで共有するNAS・SANとは対照的な、一番シンプルな接続形態として位置づけられる。","vs":"NAS・SANと混同しやすいが、DASはネットワークを経由せず1台のサーバーに直結される点が、ネットワーク越しに複数サーバーで共有できるNAS・SANとの決定的な違い。","opt":["正解。サーバーに直接接続され、そのサーバー専用のストレージ。","NASはネットワーク越しに複数のサーバーやパソコンから共有できるストレージで、直接接続ではない。","SANはストレージ専用の高速ネットワークを介して複数のサーバーとつながるストレージで、直接接続ではない。","CDNはWebコンテンツを世界中の拠点に分散配置して配信を速くする仕組みで、ストレージの接続形態の分類とは別物。"]}'),

  ('ap-server-q56', 'ストレージ技術の基礎',
   'ネットワークを経由して複数のサーバーやパソコンから共有でき、ファイル単位でデータをやり取りするストレージを何と呼ぶか。',
   NULL::text,
   '["NAS（ネットワーク接続ストレージ）", "DAS（直接接続ストレージ）", "SAN（ストレージエリアネットワーク）", "RAID"]',
   0, '[0]', 'single',
   '{"asked":"ネットワーク越しに複数の機器から共有できる、ファイル単位のストレージを選ぶ問題。","why_asked":"「ファイル単位」というアクセスの粒度が、SANの「ブロック単位」との違いを見分ける決め手になる論点。","kid":"NASはネットワークにつないでおくだけで、複数のパソコンやサーバーから「このファイルちょうだい」というふうにファイル単位でアクセスできる共有ストレージ。会社の共有フォルダのようなイメージ。","eg":"たとえるなら、みんなが使える共有の本棚のようなもの。ネットワーク越しに誰でも「この本（ファイル）を貸して」と借りられる。","terms":[["NAS","Network Attached Storageの略。直訳は「ネットワーク・接続された・ストレージ」。ネットワーク越しに複数の機器から共有できる、ファイル単位のストレージ"]],"think":"「ネットワーク経由」「複数機器で共有」「ファイル単位」という3つの特徴がNASを見分ける決め手。ファイル単位でアクセスするので、普段使っているファイルサーバーの感覚に近い。","vs":"SANと混同しやすいが、SANはブロック単位でデータをやり取りする点、NASはファイル単位でやり取りする点が違う。ブロック単位は「ディスクの一部分」を直接扱うのに対し、ファイル単位は「ファイル名で呼び出す」扱い方になる。","opt":["正解。ネットワーク越しに複数の機器から共有できる、ファイル単位のストレージ。","DASはサーバーに直接接続され、そのサーバー専用のストレージで、ネットワーク越しの共有はできない。","SANはブロック単位でデータをやり取りするストレージ専用ネットワークで、ファイル単位のNASとはアクセスの粒度が違う。","RAIDは複数のディスクを組み合わせて信頼性や速度を高める技術で、ネットワーク越しの共有形態を表す用語ではない。"]}'),

  ('ap-server-q57', 'ストレージ技術の基礎',
   'ストレージ専用の高速ネットワークを介して複数のサーバーと接続され、ブロック単位でデータをやり取りするストレージ環境を何と呼ぶか。',
   NULL::text,
   '["SAN（ストレージエリアネットワーク）", "NAS（ネットワーク接続ストレージ）", "DAS（直接接続ストレージ）", "VPN（仮想プライベートネットワーク）"]',
   0, '[0]', 'single',
   '{"asked":"ストレージ専用ネットワークを介してブロック単位でデータをやり取りする環境を選ぶ問題。","why_asked":"NASとの違い（ファイル単位かブロック単位か、専用ネットワークか通常のネットワークか）を理解しているかを問う。","kid":"SANはストレージのためだけに用意された専用の高速ネットワークで、サーバーからはディスクの一部分（ブロック）を直接やり取りするような感覚で使える。NASよりも速く、大規模なシステムでよく使われる。","eg":"たとえるなら、荷物運び専用の高速道路のようなもの。一般の道路（普通のネットワーク）とは別に、ストレージのためだけの専用ルートを用意して、大量のデータを速くやり取りする。","terms":[["SAN","Storage Area Networkの略。直訳は「ストレージ・エリア・ネットワーク」。ストレージ専用の高速ネットワークを介して複数のサーバーと接続する環境"],["ブロック単位","ファイルという単位ではなく、ディスクの中の一部分を直接読み書きする単位"]],"think":"「専用の高速ネットワーク」「ブロック単位」という2つの特徴がSANを見分ける決め手。サーバー側からは、まるでDAS(直接つながったディスク)のように扱えるが、実際にはネットワーク越しに複数サーバーで共有できるという、DASとNASのいいとこ取りのような位置づけ。","vs":"NASと混同しやすいが、NASは普段使うネットワークでファイル単位のやり取り、SANは専用ネットワークでブロック単位のやり取り、という2軸の違いがある。","opt":["正解。ストレージ専用の高速ネットワークを介して、ブロック単位でデータをやり取りする環境。","NASは普段使うネットワークを介してファイル単位で共有するストレージで、専用ネットワーク・ブロック単位のSANとは違う。","DASはサーバーに直接接続され、そのサーバー専用のストレージで、複数サーバーで共有するネットワーク環境ではない。","VPNはインターネットなどの公衆網の上に仮想的な専用線を作る技術で、ストレージの接続形態を表す用語ではない。"]}'),

  ('ap-server-q58', 'ストレージ技術の基礎',
   'NASとSANの一番の違いとして最も適切なものはどれか。',
   NULL::text,
   '["NASはファイル単位でアクセスし、SANはブロック単位でアクセスする", "NASはサーバーに直接接続され、SANはネットワークを介して接続される", "NASは1台のサーバーからしか使えず、SANは複数のサーバーから使える", "NASは読み込み専用で、SANは書き込み専用である"]',
   0, '[0]', 'single',
   '{"asked":"NASとSANの違いを一言でまとめる問題。","why_asked":"個別に学んだNASとSANの特徴を、比較の形で整理できているかを確認する総まとめの問題。","kid":"NASもSANも、どちらもネットワーク越しに複数のサーバーで共有できるストレージという点は同じ。違うのは「ファイルという単位でやり取りするか」「ディスクの一部分（ブロック）という単位でやり取りするか」という、データの扱い方の粒度。","eg":"たとえるなら、NASは「本を1冊単位で貸し借りする図書館」、SANは「本のページを直接めくって読む専用の閲覧室」のようなイメージ。どちらも複数人（複数サーバー）で使えるが、扱う単位の粒度が違う。","terms":[["ファイル単位","ファイル名を指定してデータをやり取りするアクセスの粒度"],["ブロック単位","ディスクの中の一部分を直接読み書きするアクセスの粒度"]],"think":"NASとSANはどちらも「ネットワーク越しに複数サーバーで共有できる」という共通点があるため、その違いは接続形態(ネットワークかどうか)ではなく、アクセスの単位(ファイルかブロックか)にある、という整理がポイント。","vs":"「NASはネットワーク接続、SANは直接接続」のように接続形態の違いだと誤解しやすいが、実際にはSANもネットワーク（専用の高速ネットワーク）を介して接続する点はNASと同じで、違いはアクセスの単位にある。","opt":["正解。NASはファイル単位、SANはブロック単位でアクセスするという違いがある。","NASもSANもネットワークを介して接続される点は共通しており、直接接続のDASとの違いではない。","NASもSANもどちらも複数のサーバーから利用できる点は共通している。","NASもSANも読み書きの両方が可能なストレージであり、片方だけに限定される用語ではない。"]}'),

  ('ap-server-q59', 'ストレージ技術の基礎',
   '複数のサーバーで1つのストレージを共有したい理由として最も適切なものはどれか。',
   NULL::text,
   '["各サーバーが個別にディスクを持つより、容量を柔軟に融通し合え、クラスタリングのような仕組みも組みやすくなるから", "共有すると各サーバーが使える容量が自動的に増えるから", "共有すると障害が起きたときに影響範囲を1台だけに限定できるから", "共有しないとネットワークに接続できないから"]',
   0, '[0]', 'single',
   '{"asked":"複数のサーバーでストレージを共有する目的・メリットを問う問題。","why_asked":"NAS・SANという技術の「仕組み」だけでなく、「なぜそれが欲しくなるのか」という動機を理解しているかを確認する。","kid":"各サーバーがそれぞれ自分専用のディスク（DAS）しか持たないと、あるサーバーの容量が足りなくなっても、他のサーバーの余っている容量を融通してあげることができない。ストレージを共有しておけば、必要な分だけ柔軟に割り当てたり、複数のサーバーで同じデータを見られるようにしたりできる。","eg":"たとえるなら、各部署がそれぞれ専用の倉庫を持つ（DAS）のではなく、会社全体で1つの大きな倉庫（共有ストレージ）を使えば、荷物の多い部署に多めにスペースを割り当てる、といった柔軟な運用がしやすくなるイメージ。","terms":[["クラスタリング","複数のサーバーをまとめて1つのシステムのように扱う仕組み（負荷分散と高可用性設計の分野で扱う）"]],"think":"「容量を柔軟に融通し合える」「複数サーバーで同じデータを共有できる」という点が、共有ストレージを使う一番の動機。特にクラスタリング構成（複数サーバーで同じ役割を分担する）では、どのサーバーからも同じデータにアクセスできる必要があるため、共有ストレージが前提になることが多い。","vs":"「容量が自動的に増える」という誤解に注意。共有ストレージにしても、ストレージ全体の物理的な容量が増えるわけではなく、その容量を複数サーバーで柔軟に分け合えるようになる、という点がメリット。","opt":["正解。容量を柔軟に融通し合え、クラスタリングのような複数サーバー構成も組みやすくなる。","共有すること自体で物理的な容量が自動的に増えるわけではない。","共有ストレージ自体が壊れると、それを使う複数のサーバーすべてに影響が及ぶ可能性があり、影響範囲を1台に限定できるとは言えない。","ネットワーク接続の可否は共有ストレージを使うかどうかとは別の話で、DASのサーバーも通常どおりネットワークに接続できる。"]}'),

  ('ap-server-q60', 'ストレージ技術の基礎',
   '1台のサーバーにディスクを直接つなぐDASと比べて、NAS・SANのようなネットワーク越しの共有ストレージが持つ弱点として最も適切なものはどれか。',
   NULL::text,
   '["ネットワークを経由する分、DASよりアクセスに時間がかかりやすい", "他のサーバーと共有できないため、容量の融通が利かない", "ファイルという概念そのものが存在しない", "バックアップという仕組みが一切使えなくなる"]',
   0, '[0]', 'single',
   '{"asked":"共有ストレージ(NAS・SAN)がDASと比べて持つ弱点を問う問題。","why_asked":"メリットだけでなく、共有ストレージにするとネットワークを経由する分のコストが発生するという、トレードオフの理解を確認する。","kid":"DASはサーバーに直接つながっているので、ディスクへのアクセスがとても速い。一方NAS・SANはネットワークを間に挟むぶん、直接つながっている場合より少し時間がかかりやすくなる。","eg":"たとえるなら、自分の机の引き出し(DAS)から物を取り出すのは一瞬だけど、共有の倉庫(NAS・SAN)まで取りに行くには、多少の移動時間（ネットワークを経由する時間）がかかる、というイメージ。","terms":[["ネットワーク経由","データが物理的に離れた場所とのやり取りを介すること。直接接続よりも遅延が発生しやすい"]],"think":"共有ストレージのメリット（容量の融通・複数サーバーでの共有）とのトレードオフとして、ネットワークを経由する分のわずかな遅延というコストが発生する、という因果関係で理解する。SANが専用の高速ネットワークを使うのも、この遅延をできるだけ小さくするための工夫だと位置づけられる。","vs":"「共有ストレージには弱点がない」と思いがちだが、速さの面ではDASに一日の長があり、用途に応じてDAS・NAS・SANを使い分けるという発想が実務では重要になる。","opt":["正解。ネットワークを経由する分、DASより多少アクセスに時間がかかりやすい。","NAS・SANはむしろ複数のサーバーで容量を融通し合えることが利点であり、融通が利かないという説明は逆になっている。","NASはファイル単位でアクセスする仕組みであり、ファイルという概念が存在しないというのは誤り。","NAS・SANであってもバックアップの仕組み自体は通常どおり使うことができる。"]}'),

  ('ap-server-q61', 'クラウドサービスモデル',
   'サーバーやネットワークなどのインフラだけを提供し、その上で動かすOS・ミドルウェア・アプリケーションは利用者が自分で用意・管理するクラウドサービスの形態を何と呼ぶか。',
   NULL::text,
   '["IaaS", "PaaS", "SaaS", "オンプレミス"]',
   0, '[0]', 'single',
   '{"asked":"インフラだけを提供し、OS以上は利用者が管理するクラウドサービス形態を選ぶ問題。","why_asked":"IaaS/PaaS/SaaSの3分類は、応用情報のクラウド分野で頻出。「どこまでを自分で管理するか」という責任の範囲で区別できるかを問う。","kid":"IaaSは、サーバーやネットワークといった「土台」の部分だけをクラウド事業者が用意してくれて、その上に載せるOSやアプリは全部自分で用意して管理するサービス。一番自由度が高いぶん、自分でやることも多い。","eg":"たとえるなら、更地と基礎工事だけが済んでいる土地を借りて、そこに建てる家（OSやアプリ）は自分で建てるようなイメージ。","terms":[["IaaS","Infrastructure as a Serviceの略。直訳は「サービスとしての・インフラ」。サーバーやネットワークなどのインフラだけを提供するクラウドの形態"]],"think":"「どこまでを事業者が用意し、どこからを自分で管理するか」という境目（責任分界点）で3つの形態を区別する。IaaSは境目が一番手前（インフラのすぐ上）にあり、自由度は高いが管理の手間も多い。","vs":"PaaS・SaaSと混同しやすいが、PaaSはOS・ミドルウェアまで事業者が用意し、SaaSはアプリケーションまで含めてすべて事業者が用意する点で、事業者が管理する範囲が段階的に広がっていく。","opt":["正解。インフラだけを提供し、OS以上は利用者が管理する形態。","PaaSはOS・ミドルウェアまで事業者が用意し、利用者はアプリケーションだけを用意すればよい形態。","SaaSはアプリケーションまで含めてすべて事業者が用意し、利用者はそのまま使うだけの形態。","オンプレミスはクラウドを使わず、自社の設備としてサーバーなどを保有・運用する形態で、クラウドサービスの分類ではない。"]}'),

  ('ap-server-q62', 'クラウドサービスモデル',
   'OSやデータベースなどのミドルウェアまでをクラウド事業者が用意し、利用者はその上で動かすアプリケーションの開発・配置だけに専念できるクラウドサービスの形態を何と呼ぶか。',
   NULL::text,
   '["PaaS", "IaaS", "SaaS", "ASP"]',
   0, '[0]', 'single',
   '{"asked":"OS・ミドルウェアまで提供され、アプリの開発に専念できるクラウドサービス形態を選ぶ問題。","why_asked":"IaaSとの違い（OS・ミドルウェアの管理まで事業者が引き受けるかどうか）を区別できるかを問う。","kid":"PaaSは、OSやデータベースといった「土台の上の設備」まで事業者が用意してくれるので、利用者は自分の作りたいアプリケーションを作ることだけに集中できるサービス。IaaSよりも自分でやることが少ない分、自由に選べる範囲も狭くなる。","eg":"たとえるなら、キッチン設備（OS・ミドルウェア）まで揃っているレンタルスペースを借りて、自分は料理（アプリケーション）を作ることだけに集中できるイメージ。","terms":[["PaaS","Platform as a Serviceの略。直訳は「サービスとしての・プラットフォーム」。OS・ミドルウェアまで提供し、アプリの開発に専念できるクラウドの形態"]],"think":"IaaSは「土台だけ」、PaaSは「土台＋設備」まで用意される、という段階の違いで理解する。事業者が管理してくれる範囲が広がるほど、利用者の自由度は下がるが、管理の手間も減るというトレードオフがある。","vs":"IaaSと混同しやすいが、IaaSではOSのインストールや設定まで利用者が行う必要があるのに対し、PaaSではそこまで事業者が用意してくれる点が違う。","opt":["正解。OS・ミドルウェアまで提供され、利用者はアプリケーションの開発に専念できる形態。","IaaSはインフラだけを提供し、OS・ミドルウェアの用意・管理は利用者が行う形態。","SaaSはアプリケーションまで含めてすべて事業者が用意し、利用者は開発すら行わずそのまま使う形態。","ASP(Application Service Provider)はアプリケーションをネットワーク経由で提供する古い呼び方で、現在はSaaSとほぼ同じ意味で使われることが多い、PaaSとは異なる概念。"]}'),

  ('ap-server-q63', 'クラウドサービスモデル',
   'メールサービスやオンライン会議ツールのように、アプリケーションそのものが完成した状態で提供され、利用者は開発を一切行わずそのまま使うだけのクラウドサービスの形態を何と呼ぶか。',
   NULL::text,
   '["SaaS", "IaaS", "PaaS", "オンプレミス"]',
   0, '[0]', 'single',
   '{"asked":"完成したアプリケーションをそのまま使うクラウドサービス形態を選ぶ問題。","why_asked":"3分類の中で利用者の管理範囲が最も狭い形態を、身近な具体例（メール・会議ツール）から選べるかを問う。","kid":"SaaSは、アプリケーションが完成した状態でそのまま提供され、利用者は開発も設定もほとんどせずに、すぐに使い始められるサービス。普段使っているメールサービスやオンライン会議ツールの多くがこの形態にあたる。","eg":"たとえるなら、完成した料理（アプリケーション）がそのまま出てくるレストランのようなもの。利用者(お客さん)は食べる（使う）だけでよく、キッチン設備の管理も料理も一切気にしなくてよい。","terms":[["SaaS","Software as a Serviceの略。直訳は「サービスとしての・ソフトウェア」。完成したアプリケーションをそのまま提供するクラウドの形態"]],"think":"IaaS→PaaS→SaaSの順に、事業者が用意してくれる範囲が「インフラだけ」→「OS・ミドルウェアまで」→「アプリケーションまで全部」と広がっていき、利用者がやることはどんどん少なくなっていく、という段階的な流れで整理する。","vs":"PaaSと混同しやすいが、PaaSは「アプリケーションを自分で開発する」ことが前提の形態で、SaaSは「アプリケーションが既に完成していて開発の必要がない」点が決定的に違う。","opt":["正解。アプリケーションが完成した状態で提供され、利用者はそのまま使うだけでよい形態。","IaaSはインフラだけを提供する形態で、アプリケーションの開発は利用者が行う必要がある。","PaaSはOS・ミドルウェアまで提供されるが、アプリケーションの開発自体は利用者が行う必要がある。","オンプレミスはクラウドを使わず自社設備として運用する形態で、クラウドサービスの分類ではない。"]}'),

  ('ap-server-q64', 'クラウドサービスモデル',
   'IaaS・PaaS・SaaSを、利用者が自分で管理する範囲の広さで比較したとき、正しい順番はどれか。',
   NULL::text,
   '["IaaSが一番広く自分で管理し、PaaS、SaaSの順に自分で管理する範囲が狭くなっていく", "SaaSが一番広く自分で管理し、PaaS、IaaSの順に自分で管理する範囲が狭くなっていく", "3つとも利用者が管理する範囲はまったく同じである", "IaaS・PaaSは利用者が管理するが、SaaSは事業者が一切関与しない"]',
   0, '[0]', 'single',
   '{"asked":"IaaS/PaaS/SaaSを、利用者が管理する範囲の広さで並べ替える問題。","why_asked":"個別の定義だけでなく、3つを横断的に比較・順序づけできるかという総合的な理解を問う。","kid":"IaaSは土台だけしか用意されないので、利用者が自分で管理しないといけない範囲が一番広い。PaaSはOS・ミドルウェアまで用意されるので、自分で管理する範囲がその分狭くなる。SaaSはアプリケーションまで全部用意されるので、利用者が管理する範囲は一番狭い。","eg":"たとえるなら、更地を借りるIaaS、キッチン付きの部屋を借りるPaaS、家具家電付きで住むだけのSaaS、というふうに、借りる側が自分で用意しないといけないものがだんだん減っていくイメージ。","terms":[["責任分界点","クラウド事業者と利用者のどちらが、どこからどこまでを管理する責任を持つかの境目"]],"think":"「事業者が用意してくれる範囲」と「利用者が管理する範囲」は表裏一体で、事業者が用意する範囲が広がるほど、利用者が管理する範囲は狭くなる。IaaS→PaaS→SaaSの順に、この責任分界点が利用者側からどんどん遠ざかっていく、という一貫した流れで理解する。","vs":"「管理する範囲が広い＝自由度が高い」という点も併せて理解しておくとよい。IaaSは管理の手間は多いが自由度が高く、SaaSは自由度は低いが手間がかからない、というトレードオフの関係にある。","opt":["正解。IaaS→PaaS→SaaSの順に、利用者が自分で管理する範囲は狭くなっていく。","この順番は逆になっており、実際にはIaaSの方が利用者の管理範囲が広い。","3つのサービス形態は、事業者と利用者の責任分界点の位置がそれぞれ異なる。","SaaSであっても、アプリケーションの運用・提供自体はクラウド事業者が担っており、事業者が一切関与しないわけではない。"]}'),

  ('ap-server-q65', 'クラウドサービスモデル',
   '自社でサーバーやネットワーク機器をすべて保有・運用する従来の形態（オンプレミス）と比べて、クラウドサービス（IaaS/PaaS/SaaS）に共通する特徴として最も適切なものはどれか。',
   NULL::text,
   '["インフラの一部または全部の管理を、自社からクラウド事業者に委ねられる", "オンプレミスよりも必ずセキュリティが強固になる", "オンプレミスよりも必ず利用料金が安くなる", "インフラの管理はすべて利用者自身が行う必要がある"]',
   0, '[0]', 'single',
   '{"asked":"オンプレミスと比較したときの、クラウドサービスに共通する特徴を問う問題。","why_asked":"IaaS/PaaS/SaaSという分類の違いを超えて、クラウド全体に共通する「管理を委ねられる」という本質を理解しているかを確認する。","kid":"オンプレミスは、サーバーの購入から設置、ネットワークの配線まで全部自社でやる必要がある。クラウドサービスは、IaaSでもPaaSでもSaaSでも、程度の差こそあれ、インフラの一部または全部の管理をクラウド事業者に任せられる、という点が共通している。","eg":"たとえるなら、自分で家を建てて維持する（オンプレミス）のではなく、程度の差こそあれ管理を大家さんや管理会社に任せられる賃貸（クラウド）を選ぶようなイメージ。","terms":[["オンプレミス","自社の設備としてサーバーなどを保有・運用する従来の形態"]],"think":"IaaS・PaaS・SaaSはそれぞれ「どこまで管理を委ねるか」の度合いが違うだけで、「自社だけですべて抱え込むのではなく、クラウド事業者に管理の一部を委ねられる」という点は3つとも共通している、という整理がポイント。","vs":"「クラウドは必ず安い」「クラウドは必ず安全」という決めつけに注意。コストやセキュリティは利用の仕方や規模によって変わり、一概にオンプレミスより優れているとは言い切れない。共通しているのは「管理を委ねられる」という選択肢が増える点。","opt":["正解。インフラの一部または全部の管理を、自社からクラウド事業者に委ねられる点が共通している。","セキュリティの強さは設定や運用次第であり、クラウドだからといって必ず強固になるとは限らない。","料金の安さは利用規模や使い方次第であり、クラウドだからといって必ず安くなるとは限らない。","クラウドサービスの目的の一つは、インフラ管理の一部または全部を事業者に委ねられることであり、利用者がすべて管理する必要があるという説明は逆になっている。"]}'),

  ('ap-server-q66', 'クラウドサービスモデル',
   'あるチームが「サーバーのOSやセキュリティパッチの管理はしたくないが、アプリケーションのコードは自分たちで自由に書きたい」と考えている。最も適したクラウドサービスの形態はどれか。',
   NULL::text,
   '["PaaS", "IaaS", "SaaS", "DAS"]',
   0, '[0]', 'single',
   '{"asked":"具体的な要望（OS管理はしたくないが、アプリは自分で書きたい）から、適したサービス形態を選ぶ判断問題。","why_asked":"定義の暗記だけでなく、実際の要望に照らして3つの形態を使い分けられるかという実践的な理解を問う。","kid":"「OSの管理はしたくない」ということは、OSより下は事業者に任せたいということ。「アプリは自分で書きたい」ということは、アプリの部分は自分で管理したいということ。この2つの条件をちょうど満たすのは、OS・ミドルウェアまで事業者が用意し、アプリだけを自分で書けるPaaS。","eg":"たとえるなら、「キッチン設備の管理はしたくないけど、自分で料理は作りたい」という要望に一番合うのは、キッチン付きのレンタルスペース（PaaS）を借りることで、更地（IaaS）でも完成した料理店（SaaS）でもない、というイメージ。","terms":[["PaaS","OS・ミドルウェアまで事業者が管理し、アプリケーションの開発に利用者が専念できる形態"]],"think":"要望を「どこまで管理したくないか」「どこは自分でやりたいか」の2つに分解し、その境目がIaaS・PaaS・SaaSのどの責任分界点と一致するかを考える。今回は「OSより下は任せたい／アプリは自分で書きたい」なので、境目がちょうどOSとアプリの間にあるPaaSが合う。","vs":"IaaSだとOSの管理まで自分でやる必要があり要望に合わない。SaaSだとアプリを自分で書くことができず、これも要望に合わない。要望の境目を正確に読み取ることが判断の決め手になる。","opt":["正解。OS・ミドルウェアの管理は事業者に任せつつ、アプリケーションは自分で開発できる。","IaaSではOSの管理・パッチ適用まで利用者が行う必要があり、「OSの管理はしたくない」という要望に合わない。","SaaSではアプリケーションが完成した状態で提供され、自分でコードを書く余地がなく、「自由に書きたい」という要望に合わない。","DASはサーバーに直結されたストレージの接続形態を表す用語で、クラウドサービスの提供形態の分類ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-server'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
